using System.IdentityModel.Tokens.Jwt;using System.Security.Claims;using System.Text;using Microsoft.AspNetCore.Authentication.JwtBearer;using Microsoft.AspNetCore.Identity;using Microsoft.EntityFrameworkCore;using Microsoft.IdentityModel.Tokens;using Visitors.Api.Data;using Visitors.Api.Models;using Visitors.Api.Services;
var b=WebApplication.CreateBuilder(args);var secret=b.Configuration["Jwt:Secret"]??"development-only-secret-change-me-32-characters";b.Services.AddDbContext<VisitorsDbContext>(o=>o.UseSqlite(b.Configuration.GetConnectionString("Default")??"Data Source=visitors.db"));b.Services.AddScoped<IPasswordHasher<User>,PasswordHasher<User>>();b.Services.AddScoped<VisitService>();b.Services.AddOpenApi();b.Services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme).AddJwtBearer(o=>o.TokenValidationParameters=new(){ValidateIssuer=false,ValidateAudience=false,ValidateLifetime=true,ValidateIssuerSigningKey=true,IssuerSigningKey=new SymmetricSecurityKey(Encoding.UTF8.GetBytes(secret))});b.Services.AddAuthorization();var app=b.Build();app.UseExceptionHandler("/error");app.UseAuthentication();app.UseAuthorization();if(app.Environment.IsDevelopment())app.MapOpenApi();app.Map("/error",()=>Results.Json(new{error=new{code="SERVER_ERROR",message="Request could not be completed"}},statusCode:500));
app.MapPost("/api/auth/login",async(Login x,VisitorsDbContext db,IPasswordHasher<User> h)=>{var u=await db.Users.SingleOrDefaultAsync(y=>y.Username==x.Username);if(u==null||h.VerifyHashedPassword(u,u.PasswordHash,x.Password)==PasswordVerificationResult.Failed)return Results.Unauthorized();var cs=new[]{new Claim(ClaimTypes.NameIdentifier,u.Id.ToString()),new Claim(ClaimTypes.Name,u.Username),new Claim(ClaimTypes.Role,u.Role)};var token=new JwtSecurityTokenHandler().WriteToken(new JwtSecurityToken(claims:cs,expires:DateTime.UtcNow.AddHours(2),signingCredentials:new(new SymmetricSecurityKey(Encoding.UTF8.GetBytes(secret)),SecurityAlgorithms.HmacSha256)));return Results.Ok(new{data=new{token,user=new{u.Id,u.Username,u.Role}}});});var staff=new[]{"Admin","Reception","Security"};
app.MapGet("/api/visitors",async(string? search,int page,int limit,VisitorsDbContext db)=>{page=Math.Max(1,page);limit=Math.Clamp(limit==0?20:limit,1,100);var q=db.Visitors.AsNoTracking();if(!string.IsNullOrWhiteSpace(search))q=q.Where(x=>x.FullName.Contains(search)||x.Email.Contains(search));return Results.Ok(new{data=await q.OrderBy(x=>x.FullName).Skip((page-1)*limit).Take(limit).ToListAsync(),pagination=new{page,limit,total=await q.CountAsync()}});}).RequireAuthorization(p=>p.RequireRole(staff));
app.MapPost("/api/visitors",async(VisitorInput x,VisitorsDbContext db)=>{if(string.IsNullOrWhiteSpace(x.FullName)||!x.Email.Contains('@'))return Results.BadRequest();if(await db.Visitors.AnyAsync(v=>v.Email==x.Email.ToLower()))return Results.Conflict();var v=new Visitor{FullName=x.FullName.Trim(),Email=x.Email.Trim().ToLowerInvariant(),Phone=x.Phone.Trim(),Company=x.Company?.Trim()??""};db.Add(v);await db.SaveChangesAsync();return Results.Created($"/api/visitors/{v.Id}",new{data=v});}).RequireAuthorization(p=>p.RequireRole("Admin","Reception"));
app.MapGet("/api/visits",async(string? status,DateOnly? date,int page,int limit,VisitorsDbContext db)=>{page=Math.Max(1,page);limit=Math.Clamp(limit==0?20:limit,1,100);var q=db.Visits.AsNoTracking().Include(x=>x.Visitor).AsQueryable();if(!string.IsNullOrWhiteSpace(status))q=q.Where(x=>x.Status==status);if(date!=null){var start=date.Value.ToDateTime(TimeOnly.MinValue,DateTimeKind.Utc);var end=start.AddDays(1);q=q.Where(x=>x.ScheduledAt>=start&&x.ScheduledAt<end);}return Results.Ok(new{data=await q.OrderByDescending(x=>x.ScheduledAt).Skip((page-1)*limit).Take(limit).ToListAsync(),pagination=new{page,limit,total=await q.CountAsync()}});}).RequireAuthorization(p=>p.RequireRole(staff));
app.MapPost("/api/visits",async(VisitInput x,ClaimsPrincipal u,VisitorsDbContext db)=>{if(x.ScheduledAt<DateTime.UtcNow.AddMinutes(-5)||string.IsNullOrWhiteSpace(x.HostName)||string.IsNullOrWhiteSpace(x.Purpose))return Results.BadRequest();if(!await db.Visitors.AnyAsync(v=>v.Id==x.VisitorId))return Results.NotFound();if(await db.Visits.AnyAsync(v=>v.VisitorId==x.VisitorId&&v.Status==VisitStatuses.Expected&&v.ScheduledAt.Date==x.ScheduledAt.Date))return Results.Conflict(new{error=new{code="DUPLICATE_VISIT",message="Visitor already has an expected visit that day"}});var visit=new Visit{Reference=$"VST-{Guid.NewGuid().ToString("N")[..10].ToUpperInvariant()}",VisitorId=x.VisitorId,HostName=x.HostName.Trim(),Purpose=x.Purpose.Trim(),ScheduledAt=x.ScheduledAt.ToUniversalTime(),CreatedById=int.Parse(u.FindFirstValue(ClaimTypes.NameIdentifier)!)};db.Add(visit);await db.SaveChangesAsync();return Results.Created($"/api/visits/{visit.Id}",new{data=visit});}).RequireAuthorization(p=>p.RequireRole("Admin","Reception"));
app.MapPatch("/api/visits/{id:int}/check-in",async(int id,BadgeInput x,VisitService s)=>{try{return Results.Ok(new{data=await s.CheckInAsync(id,x.BadgeNumber)});}catch(KeyNotFoundException){return Results.NotFound();}catch(ArgumentException e){return Results.BadRequest(new{error=new{code="VALIDATION_ERROR",message=e.Message}});}catch(InvalidOperationException e){return Results.Conflict(new{error=new{code="CONFLICT",message=e.Message}});}}).RequireAuthorization(p=>p.RequireRole(staff));
app.MapPatch("/api/visits/{id:int}/check-out",async(int id,VisitService s)=>{try{return Results.Ok(new{data=await s.CheckOutAsync(id)});}catch(KeyNotFoundException){return Results.NotFound();}catch(InvalidOperationException e){return Results.Conflict(new{error=new{code="CONFLICT",message=e.Message}});}}).RequireAuthorization(p=>p.RequireRole(staff));
app.MapGet("/api/dashboard",async(VisitorsDbContext db)=>Results.Ok(new{data=new{expected=await db.Visits.CountAsync(x=>x.Status==VisitStatuses.Expected),inside=await db.Visits.CountAsync(x=>x.Status==VisitStatuses.CheckedIn),completedToday=await db.Visits.CountAsync(x=>x.Status==VisitStatuses.CheckedOut&&x.CheckedOutAt!.Value.Date==DateTime.UtcNow.Date)}})).RequireAuthorization(p=>p.RequireRole(staff));
await using(var scope=app.Services.CreateAsyncScope()){var db=scope.ServiceProvider.GetRequiredService<VisitorsDbContext>();await db.Database.EnsureCreatedAsync();if(!await db.Users.AnyAsync()){var h=scope.ServiceProvider.GetRequiredService<IPasswordHasher<User>>();foreach(var(n,r)in new[]{("admin","Admin"),("reception","Reception"),("security","Security")}){var u=new User{Username=n,Role=r,PasswordHash="x"};u.PasswordHash=h.HashPassword(u,"ChangeMe123!");db.Add(u);}db.Visitors.Add(new Visitor{FullName="Demo Visitor",Email="visitor@example.com",Phone="555-0100",Company="Example Co"});await db.SaveChangesAsync();}}
app.Run();public partial class Program;public sealed record Login(string Username,string Password);public sealed record VisitorInput(string FullName,string Email,string Phone,string? Company);public sealed record VisitInput(int VisitorId,string HostName,string Purpose,DateTime ScheduledAt);public sealed record BadgeInput(string BadgeNumber);
